/**
 * Jinx Butler + Cannibal: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Butler
 * Wiki: https://wiki.bloodontheclocktower.com/Cannibal
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`. Each test quotes the wiki text it encodes word
 * for word in a `// Wiki: "..."` comment (CLAUDE.md, Trevor 2026-11-01 and 2026-11-02).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong, type Script } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { scenario, type Scenario } from '#lib/core/testing/scenario.ts';
import { gainedAbilities, withGainedSteps } from '#lib/core/rules/gained-abilities.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { nightStepAlerts } from '#lib/core/rules/night-alerts.ts';

const scriptOf = (ids: string[]): Script => ({
	meta: { name: 'Jinxed' },
	entries: ids.map((id) => ({ kind: 'official' as const, id }))
});
const script = scriptOf(['cannibal', 'butler', 'imp', 'chef', 'empath', 'monk', 'poisoner']);

/** The Cannibal's gained step tonight, and what it says they learn. */
const gainedStep = (s: Scenario) =>
	withGainedSteps([], s.game, s.characters, 'other').find((step) => step.gained);
const learns = (s: Scenario) =>
	nightStepAlerts(s.game, 'cannibal', s.characters).filter((a) => a.kind === 'learns-gained');

describe('Butler + Cannibal jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'butler', 'cannibal');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('butler')?.name).toBe('Butler');
		expect(data.byId.get('cannibal')?.name).toBe('Cannibal');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['butler', 'cannibal'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['butler'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['cannibal'])).not.toContain(jinx);
	});

	describe('the Cannibal who gains the Butler ability learns it', () => {
		// The day's execution of the Butler, with Lunch on them: the Cannibal now has the Butler
		// ability, and tonight's step wakes them with it.
		const eaten = scenario(['cannibal', 'butler', 'imp', 'poisoner', 'empath'], { script })
			.execute('butler')
			.reminder('butler', 'cannibal', 'Lunch');

		it("is data in the Cannibal's rules", () => {
			expect(jinxRulesBetween('cannibal', 'butler')).toEqual({ learnsGained: 'ability' });
		});

		it('the night after the Butler is executed, the Cannibal step says they learn it', () => {
			// Wiki: "If the Cannibal gains the Butler ability, the Cannibal learns this."
			const step = gainedStep(eaten);
			expect(step?.gained).toMatchObject({
				seatId: eaten.seat('cannibal'),
				characterId: 'butler',
				learns: 'ability'
			});
			// The Butler's own night text: the Cannibal chooses a Master as well.
			expect(step?.reminder).toBe(eaten.characters.get('butler')?.otherNightReminder);
			expect(learns(eaten)).toMatchObject([
				{
					seatId: eaten.seat('cannibal'),
					source: { characterId: 'butler', seatId: eaten.seat('cannibal') },
					works: true,
					learns: 'ability'
				}
			]);
		});

		it('only on that night: by the next night the Cannibal already knows', () => {
			// Wiki: "If the Cannibal gains the Butler ability, the Cannibal learns this."
			const later = eaten.newDay().dusk();
			expect(gainedAbilities(later.game, later.characters)).toMatchObject([
				{ characterId: 'butler' }
			]);
			expect(gainedStep(later)?.gained?.learns).toBeUndefined();
			expect(learns(later)).toEqual([]);
		});

		it('without the jinx the Cannibal is not told which ability they gained', () => {
			// Wiki: "The Cannibal is not told which ability they have gained. They must figure that
			// out for themselves."
			const monk = scenario(['cannibal', 'monk', 'imp', 'chef', 'empath'], { script })
				.execute('monk')
				.reminder('monk', 'cannibal', 'Lunch');
			expect(gainedStep(monk)?.gained).toMatchObject({ characterId: 'monk' });
			expect(gainedStep(monk)?.gained?.learns).toBeUndefined();
			expect(learns(monk)).toEqual([]);
		});

		it('a poisoned Cannibal is still shown it, as not working: the Storyteller decides', () => {
			// Wiki: "If the Cannibal gains the Butler ability, the Cannibal learns this."
			expect(learns(eaten.poisoned('cannibal'))).toMatchObject([
				{ works: false, learns: 'ability' }
			]);
		});
	});
});
